insert into gate_review (id, job_book_id, gate, attempt, outcome, chaired_by, custodian_id, project_manager_id, decided_at, criteria_snapshot, completion_pct, override_note, conditional_due_at) values
  ('d0d0d0d0-c31d-ff39-d8b1-3754f63f592d', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G0', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-03-09T17:00:00Z', '[{"id":"g0.scaffolded","gate":"G0","text":"Job book created from the correct template with all applicable sections scaffolded and non applicable sections marked N/A with a recorded reason.","source":"derived","state":"met"},{"id":"g0.custodian","gate":"G0","text":"Job Book Custodian named in writing and holding competency level JB-2 or above.","source":"derived","state":"met"},{"id":"g0.governing_docs","gate":"G0","text":"Client checklist revision and client piping specification revision recorded and confirmed current with the client.","source":"derived","state":"met"},{"id":"g0.procedures_loaded","gate":"G0","text":"Section 3 piping specification, Section 4 WPS, Section 5 PQR and Section 9 NDT procedures loaded and legible.","source":"derived","state":"met"},{"id":"g0.wpq","gate":"G0","text":"Section 6 WPQ on file, current, and valid through the planned work window for every welder mobilizing.","source":"derived","state":"met"},{"id":"g0.inspector_creds","gate":"G0","text":"Section 7 CWI credentials and Section 8 NDT technician credentials on file and current for every inspector mobilizing.","source":"derived","state":"met"},{"id":"g0.wrench_calibration","gate":"G0","text":"Section 13 calibration certificates on file and current for every torque wrench mobilizing, with each wrench entered in the controlled wrench register.","source":"derived","state":"met"},{"id":"g0.expected_by","gate":"G0","text":"Section expected by dates set against the construction schedule.","source":"derived","state":"met"},{"id":"g0.planned_curve","gate":"G0","text":"Planned completion curve agreed and recorded.","source":"derived","state":"met"}]', 90.77, null, null),
  ('d0d0d0d0-1e82-1407-afda-e75fe247c065', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G1', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-05-08T17:00:00Z', '[{"id":"g1.curve","gate":"G1","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met"},{"id":"g1.timeliness","gate":"G1","text":"Entry timeliness rate at or above 95% for the period.","source":"derived","state":"met"},{"id":"g1.self_audit","gate":"G1","text":"All scheduled Tier 1 self audits performed, signed and on file.","source":"derived","state":"not_met"},{"id":"g1.peer_audit","gate":"G1","text":"First Tier 2 peer audit performed, scored at 90 or above, with zero Critical findings.","source":"derived","state":"met"},{"id":"g1.registers","gate":"G1","text":"Controlled registers populated: welders, wrenches, heats, isometric drawings.","source":"derived","state":"met"},{"id":"g1.heats","gate":"G1","text":"Heat register reconciled. Every heat referenced by a weld has an MTR on file.","source":"derived","state":"met"},{"id":"g1.ncr","gate":"G1","text":"Zero open NCRs past due date.","source":"derived","state":"met"}]', 90.77, 'Demo book. 1 criterion unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-a070-6ef8-87fb-212c7f5c51ea', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G2', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-07-07T17:00:00Z', '[{"id":"g2.gate1_sustained","gate":"G2","text":"All Gate 1 criteria, sustained.","source":"derived","state":"not_met"},{"id":"g2.curve","gate":"G2","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met"},{"id":"g2.iso_stage1","gate":"G2","text":"Isometric markup stage 1 complete for every construction area at mechanical completion.","source":"derived","state":"indeterminate"},{"id":"g2.pressure_closed","gate":"G2","text":"Pressure test packages closed for every test performed to date, including result documents.","source":"derived","state":"met"},{"id":"g2.cert_forecast","gate":"G2","text":"Certificate expiry forecast reviewed. No certificate expires inside the remaining work window without a requalification plan on file.","source":"derived","state":"met"},{"id":"g2.peer_audit","gate":"G2","text":"Tier 2 peer audit scored at 90 or above with zero Critical findings.","source":"derived","state":"met"}]', 90.77, 'Demo book. 2 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-3c47-8014-34ea-2de49e4854aa', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G3', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-09-05T17:00:00Z', '[{"id":"g3.records_entered","gate":"G3","text":"All field records entered. Zero records outstanding.","source":"derived","state":"not_met"},{"id":"g3.iso_stages","gate":"G3","text":"Isometric markup stages 1 and 2 complete for all areas.","source":"derived","state":"indeterminate"},{"id":"g3.nde","gate":"G3","text":"All NDE reports received, filed and linked to weld records.","source":"derived","state":"met"},{"id":"g3.pressure","gate":"G3","text":"All pressure and hydro test packages complete with hold data, result documents and valid on test date instrument certificates.","source":"derived","state":"met"},{"id":"g3.heats","gate":"G3","text":"Heat register fully reconciled in both directions: no installed heat without an MTR, and every MTR on file traceable to an installed heat.","source":"derived","state":"met"},{"id":"g3.coating","gate":"G3","text":"Coating inspection records complete for all areas requiring them, where the section is enabled.","source":"derived","state":"met"},{"id":"g3.backlog","gate":"G3","text":"Document backlog at zero. Nothing unfiled.","source":"attested","state":"indeterminate"}]', 90.77, 'Demo book. 3 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null)
